function playbackProject(){syncSection(p);return playScope==='song'&&p.arrangement.length?compileSong(p):structuredClone(p)}
function currentPosition(){if(transport?.practice)return playbackPosition(transport,audio.ctx.currentTime);if(transport){const raw=(audio.ctx.currentTime-transport.start)/transport.sec;return {beat:Math.max(0,raw%totalBeats(transport.project)),counting:raw<0,remaining:Math.ceil(-raw),tempo:p.bpm,pass:1}}return {beat:playCursor,counting:false,tempo:p.bpm,pass:1}}
function refreshPractice(){practicePreview=playbackProject();playCursor=Math.max(0,Math.min(playCursor,totalBeats(practicePreview)-.25));renderPracticeBar($('#rehearsal-dock'),practicePreview,p.rehearsal,playCursor,{seek:seekTo,change:settings=>{stop();p.rehearsal=settings;save();refreshPractice()},jump:beat=>seekTo(beat)});updateMusicalContext();}
function seekTo(beat){const was=!!transport&&!transport.recording;stop();const project=playbackProject();playCursor=Math.max(0,Math.min(Number(beat)||0,totalBeats(project)-.25));refreshPractice();if(view==='my-part')renderPartView();if(was)startPlayback();}
function applyListeningMix(){if(!transport?.practice)return;const tr=transport;if(tr.scorePreview){for(const t of tr.project.tracks){const live=p.tracks.find(x=>x.id===t.id);if(live){const mix={volume:live.volume,pan:live.pan,reverbSend:live.reverbSend};Object.assign(t,mix);if(tr.scoreSourceTrack?.id===t.id)Object.assign(tr.scoreSourceTrack,mix);}}audio.applyMix({...p,tracks:tr.project.tracks});return;}for(const t of tr.project.tracks){const live=p.tracks.find(x=>x.id===t.id);if(live)Object.assign(t,{volume:live.volume,pan:live.pan,reverbSend:live.reverbSend,muted:live.muted,solo:live.solo})}tr.audible=new Set(listeningTracks(tr.project,tr.listen,tr.part).map(t=>t.id));const mix={...p,tracks:tr.project.tracks.map(t=>({...t,muted:!tr.audible.has(t.id),solo:false}))};audio.applyMix(mix);}
async function startPlayback(){if(busy)return;if(transport){stop();return}const request=++playbackRequest;busy=true;try{if(!p.tracks.length){toast('Add a part to begin.');return}const playing=playbackProject();$('#transport-state').textContent='LOADING';await audio.prepareProject(playing);if(request!==playbackRequest)return;const tr=createPlayback(playing,p.rehearsal,playCursor,audio.ctx.currentTime,p.loop);tr.scope=playScope;tr.listen=view==='my-part'?(p.partListen||'ensemble'):'ensemble';tr.part=practicePart||activeTrack()?.id||p.tracks[0]?.id;tr.recorded=new Map();transport=tr;applyListeningMix();tr.timer=setInterval(schedule,25);$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause playback');$('#play').classList.add('playing');schedule();raf=requestAnimationFrame(tick)}catch(e){toast(e.message);stop()}finally{busy=false}}
function schedulePlayback(){const tr=transport,now=audio.ctx.currentTime,horizon=now+.12;applyListeningMix();for(const item of scheduledNotes(tr,tr.from,horizon)){const {track:t,event:e,at,sec}=item;if(!tr.audible.has(t.id))continue;const inst=getInstrument(t.instrument);audio.play(inst,{...e,duration:e.duration*sec*p.bpm/60},tr.scoreSourceTrack||t,at);const ix=notesFor(inst,p.key).findIndex(n=>n.note===e.note&&(n.shift||0)===(e.shift||0));const handle=setTimeout(()=>{if(transport!==tr)return;flash(inst.id,ix,inst.shape==='recorder'?e.duration*sec:.16,t.id);notesTimeouts.delete(handle)},Math.max(0,(at-now)*1000));notesTimeouts.add(handle);}
 for(const click of scheduledClicks(tr,tr.from,horizon,metro))audio.click(Math.max(click.at,now),click.accent,metroVolume);tr.from=horizon;while(tr.passes.length>1&&tr.passes[0].end<=now)tr.passes.shift();if(!tr.repeat&&now>=tr.passes.at(-1).end){stop(false);if(!tr.scorePreview){playCursor=tr.range.a;refreshPractice();toast('Playback finished.')}}}
function renderPartView(){cancelAnimationFrame(practiceFrame);if(!p.tracks.length){$('#content').innerHTML=header('CLASSROOM PRACTICE','My Part','Add an instrument to start rehearsing.');return}practicePart=p.tracks.some(t=>t.id===practicePart)?practicePart:activeTrack()?.id||p.tracks[0].id;const preview=playbackProject();renderMyPart($('#content'),p,preview,practicePart,{artwork,choose:id=>{const was=!!transport;stop();practicePart=id;renderPartView();updateMusicalContext();if(was)startPlayback()},listen:mode=>{p.partListen=mode;save();if(transport?.practice){transport.listen=mode;transport.part=practicePart;applyListeningMix()}},seek:seekTo});const frame=()=>{if(view!=='my-part')return;const pos=currentPosition();updateMyPart($('#content'),p,transport?.project||preview,practicePart,pos,!!transport&&!pos.counting);practiceFrame=requestAnimationFrame(frame)};frame();}

