 try{const inst=getInstrument(track.instrument);await audio.load(inst,n.note,n.shift||0);if(request!==playbackRequest||view!=='score'||activeTrack()?.id!==track.id||p.activeSection!==section)return;audio.applyMix(p);audio.play(inst,{...n,duration:Math.min(length,2),velocity:.7},track);}catch(e){toast(e.message);}
