 $$('[data-version-download]').forEach(b=>b.onclick=()=>{const v=versions.find(v=>v.id===b.dataset.versionDownload);download(new Blob([JSON.stringify(v.project,null,2)],{type:'application/json'}),filename()+'-'+v.name.replace(/[^a-z0-9-]/gi,'-')+'.orff');});
