 $$('[data-version-delete]').forEach(b=>b.onclick=()=>{const v=versions.find(v=>v.id===b.dataset.versionDelete);confirmAction('Delete saved version?', 'Remove “'+v.name+'” from this browser? Your current composition stays unchanged. Download this version first if you need a backup.',()=>{try{deleteVersion(localStorage,p.projectId,v.id);versionsDialog();}catch(e){toast(e.message);}});});
